/*---
description: NFKD agrees with Node for every code point U+000000 through U+00FFFF.
features: [ts-unicode-normalization, ts-strings, ts-iteration, ts-arrays, ts-unicode-exhaustive]
---*/
// Generated by tooling/unicode-cases/normalization.ts; Unicode 17.0, ICU 78.3.
// Contract: docs/foundations/unicode.md, Staying identical to node.
// Each FNV-1a digest consumes normalized UTF-16 code units in code-point order.
// The BMP plane includes every lone surrogate U+D800-U+DFFF.
const expected = [467995593, 3391332930, 1567289126, 2093032683, 3680693701, 2194763205, 2892066245, 1899982277, 362769861, 2643684805, 3982155614, 3221453953, 4108245472, 187347594, 1459252677, 1892202347];
const blocks = ["NFKD U+000000-U+000FFF", "NFKD U+001000-U+001FFF", "NFKD U+002000-U+002FFF", "NFKD U+003000-U+003FFF", "NFKD U+004000-U+004FFF", "NFKD U+005000-U+005FFF", "NFKD U+006000-U+006FFF", "NFKD U+007000-U+007FFF", "NFKD U+008000-U+008FFF", "NFKD U+009000-U+009FFF", "NFKD U+00A000-U+00AFFF", "NFKD U+00B000-U+00BFFF", "NFKD U+00C000-U+00CFFF", "NFKD U+00D000-U+00DFFF", "NFKD U+00E000-U+00EFFF", "NFKD U+00F000-U+00FFFF"];
for (let block = 0; block < expected.length; block++) {
  let hash = 2166136261;
  const start = 0 + block * 4096;
  for (let point = start; point < start + 4096; point++) {
    const output = String.fromCodePoint(point).normalize("NFKD");
    for (let unit = 0; unit < output.length; unit++) {
      hash = Math.imul(hash ^ output.charCodeAt(unit), 16777619) >>> 0;
    }
  }
  assert.sameValue(hash, expected[block], blocks[block]);
}
